// ApiServer is the server API for Api service.
type ApiServer interface {
	EnqueJob(context.Context, *FeedJob) (*FeedJob, error)
	GetFeedJob(context.Context, *Worker) (*FeedJob, error)
	FinishJob(context.Context, *FeedJob) (*FeedJob, error)
	EnqueueTask(context.Context, *EnqueueTaskRequest) (*EnqueueTaskResponse, error)
	ClaimTasks(context.Context, *ClaimTasksRequest) (*ClaimTasksResponse, error)
	CompleteTask(context.Context, *CompleteTaskRequest) (*emptypb.Empty, error)
	FailTask(context.Context, *FailTaskRequest) (*FailTaskResponse, error)
	RenewTaskLease(context.Context, *RenewTaskLeaseRequest) (*Task, error)
	FetchProfile(context.Context, *ProfileRequest) (*Profile, error)
	FetchGraph(context.Context, *ProfileRequest) (*Graph, error)
	GraphFollow(context.Context, *FollowRequest) (*FollowResponse, error)
	// rpc FetchFeedinfo(ProfileRequest) returns (Feedinfo) {}
	PostFeedinfo(context.Context, *Feedinfo) (*Profile, error)
	// A client-to-server streaming RPC.
	//
	// Accepts a stream of Entries on a feed being archived, returning a
	// FeedSummary when archving is completed.
	ArchiveFeed(Api_ArchiveFeedServer) error
	ForceArchiveFeed(Api_ForceArchiveFeedServer) error
	FetchFeed(context.Context, *FeedRequest) (*Feed, error)
	FetchInteractionFeed(context.Context, *InteractionFeedRequest) (*InteractionFeedResponse, error)
	// Entry page return Feed as well
	FetchEntry(context.Context, *EntryRequest) (*Feed, error)
	PostEntry(context.Context, *Entry) (*Entry, error)
	PostTweet(context.Context, *Tweet) (*Entry, error)
	DeleteEntry(context.Context, *EntryRequest) (*EntryRequest, error)
	LikeEntry(context.Context, *LikeRequest) (*Entry, error)
	CommentEntry(context.Context, *CommentRequest) (*Entry, error)
	DeleteComment(context.Context, *CommentDeleteRequest) (*Entry, error)
	Search(context.Context, *SearchRequest) (*Feed, error)
	PutOAuth(context.Context, *OAuthUser) (*Profile, error)
	// rpc BindAuth(OAuthUser) returns (OAuthUser) {}
	BindUserFeed(context.Context, *OAuthUser) (*OAuthUser, error)
	// service
	AddFeedService(context.Context, *AddFeedServiceRequest) (*FeedService, error)
	RemoveFeedService(context.Context, *RemoveFeedServiceRequest) (*emptypb.Empty, error)
	ListFeedServices(context.Context, *ListFeedServicesRequest) (*ListFeedServicesResponse, error)
	SetFeedServiceEnabled(context.Context, *SetFeedServiceEnabledRequest) (*FeedService, error)
	RefreshFeedService(context.Context, *RefreshFeedServiceRequest) (*emptypb.Empty, error)
	// group
	CreateGroup(context.Context, *CreateGroupRequest) (*Profile, error)
	JoinGroup(context.Context, *GroupMembershipRequest) (*emptypb.Empty, error)
	LeaveGroup(context.Context, *GroupMembershipRequest) (*emptypb.Empty, error)
	AddGroupAdmin(context.Context, *GroupMembershipRequest) (*emptypb.Empty, error)
	RemoveGroupAdmin(context.Context, *GroupMembershipRequest) (*emptypb.Empty, error)
	RemoveGroupMember(context.Context, *GroupMembershipRequest) (*emptypb.Empty, error)
	UpdateGroup(context.Context, *UpdateGroupRequest) (*Profile, error)
	DeleteGroup(context.Context, *DeleteGroupRequest) (*emptypb.Empty, error)
	GetGroup(context.Context, *GetGroupRequest) (*GroupView, error)
	ListGroupMembers(context.Context, *ListGroupMembersRequest) (*ListGroupMembersResponse, error)
	ListUserGroups(context.Context, *ListUserGroupsRequest) (*ListUserGroupsResponse, error)
	RequestFollow(context.Context, *RequestFollowRequest) (*RequestFollowResponse, error)
	CancelFollowRequest(context.Context, *RequestFollowRequest) (*emptypb.Empty, error)
	ApproveFollowRequest(context.Context, *FollowRequestAction) (*emptypb.Empty, error)
	RejectFollowRequest(context.Context, *FollowRequestAction) (*emptypb.Empty, error)
	ListFollowRequests(context.Context, *ListFollowRequestsRequest) (*ListFollowRequestsResponse, error)
	Command(context.Context, *CommandRequest) (*CommandResponse, error)
	// Stock
	ArchiveRawdata(Api_ArchiveRawdataServer) error
	// Stream:ArchiveKLine
	ArchiveKLine(Api_ArchiveKLineServer) error
	// Stream:ArchiveXRXD
	ArchiveXRXD(Api_ArchiveXRXDServer) error
	ArchiveFundamental(Api_ArchiveFundamentalServer) error
	ArchiveStockInfo(Api_ArchiveStockInfoServer) error
	GetXRXD(context.Context, *StockRequest) (*XRXDResponse, error)
	GetKLines(context.Context, *StockRequest) (*KLineResponse, error)
	UpdateStockList(context.Context, *StockList) (*Response, error)
	UpdateRawdata(context.Context, *Rawdata) (*Response, error)
	GetRawdata(context.Context, *StockRequest) (*Rawdata, error)
	GetStockList(context.Context, *StockRequest) (*StockList, error)
	GetStock(context.Context, *StockRequest) (*Stock, error)
	GetStockInfo(context.Context, *StockRequest) (*StockInfo, error)
	GetFundamental(context.Context, *StockRequest) (*Fundamental, error)
	DeleteRawdata(context.Context, *Rawdata) (*Response, error)
	SendReport(context.Context, *Report) (*Response, error)
}

